local G={}
local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function decode(s)
 local digits,out={},{};for i=1,#alphabet do digits[alphabet:sub(i,i)]=i-1 end
 for i=1,#s,4 do
  local a,b,c,d=digits[s:sub(i,i)],digits[s:sub(i+1,i+1)],digits[s:sub(i+2,i+2)],digits[s:sub(i+3,i+3)]
  out[#out+1]=string.char(a*4+math.floor(b/16),(b%16)*16+math.floor(c/4),(c%4)*64+d)
 end
 return table.concat(out)
end
local batons={crowbar=true,bat=true,baseball_bat=true,club=true,baton=true}
function G.isBaton(id)return not not batons[id]end
function G.guard(clips,id)return G.isBaton(id)and G.ready or clips.guard end

