 local ax,ay,az=r[4],r[5],r[6];local n=math.sqrt(ax^2+ay^2+az^2);ax,ay,az=ax/n,ay/n,az/n
 local bx,by,bz=r[7],r[8],r[9];local dot=ax*bx+ay*by+az*bz
 bx,by,bz=bx-dot*ax,by-dot*ay,bz-dot*az;n=math.sqrt(bx^2+by^2+bz^2);bx,by,bz=bx/n,by/n,bz/n
 local cx,cy,cz=ay*bz-az*by,az*bx-ax*bz,ax*by-ay*bx
 local sign=cx*r[10]+cy*r[11]+cz*r[12]<0 and -1 or 1
 r[4],r[5],r[6],r[7],r[8],r[9],r[10],r[11],r[12]=ax,ay,az,bx,by,bz,cx*sign,cy*sign,cz*sign
 return r
end
function G.socket(name,position,out)
 local frames=sockets[name]or sockets.idle;local i=math.max(0,math.min(#frames-1,position));local k=math.floor(i)+1;local t=i-math.floor(i);local a,b=frames[k],frames[math.min(k+1,#frames)];local result=out or {}
 for n=1,12 do result[n]=a[n]+(b[n]-a[n])*t end
 -- A fixed palm-local grip follows wrist rotation; no world-axis clamping or roll flips.
 local weight=(name=='idle'or name=='walk'or name=='run')and 1 or 0

 if weight>0 then
  local rotation,old=gripRotation,rotationScratch;for i=4,12 do old[i]=result[i]end
  for axis=1,3 do for k=1,3 do
   local value=0;for j=1,3 do value=value+old[3+(j-1)*3+k]*rotation[axis][j]end
   local n=3+(axis-1)*3+k;result[n]=old[n]+(value-old[n])*weight
  end end
 end
 return orthonormal(result)
end

-- Blend only combat stance changes; walking/running cadence is untouched.
local previousName,lastPose,lastSocket,fromPose,fromSocket,elapsed,alpha
local socketFrom={}
local poseA,poseB={},{}
-- Fixed flat buffers: switching stance must not allocate 408 vertex tables.
for i=1,408*3 do poseA[i]=0;poseB[i]=0 end
lastPose=poseA;elapsed=1;alpha=1
local poseCount=0
function G.preparePose(name,dt)
 if name~=previousName then
  if previousName and(name=='ready'or previousName=='ready'or previousName=='swing'or name=='run'or previousName=='run'or name=='walk'or previousName=='walk')then
   fromPose=lastPose;lastPose=lastPose==poseA and poseB or poseA
   if lastSocket then for i=1,12 do socketFrom[i]=lastSocket[i]end;fromSocket=socketFrom else fromSocket=nil end;elapsed=0
  else fromPose=nil;fromSocket=nil;elapsed=1 end
 end
 previousName=name;elapsed=elapsed+dt;alpha=math.min(1,elapsed/.18)
 if alpha>=1 then fromPose=nil;fromSocket=nil end
end
function G.blendVertex(i,x,y,z)
 local p=(i-1)*3
 if fromPose and i<=poseCount then x=fromPose[p+1]+(x-fromPose[p+1])*alpha;y=fromPose[p+2]+(y-fromPose[p+2])*alpha;z=fromPose[p+3]+(z-fromPose[p+3])*alpha end
 lastPose[p+1],lastPose[p+2],lastPose[p+3]=x,y,z
 if i>poseCount then poseCount=i end
 return x,y,z
end
function G.blendSocket(socket,out)
 local r=out or {};for i=1,12 do r[i]=fromSocket and(fromSocket[i]+(socket[i]-fromSocket[i])*alpha)or socket[i]end
 orthonormal(r);lastSocket=r;return r
end
function G.stable()return alpha>=1 end
return G
